script:
(function () {
  'use strict';
  // Credit union share certificate ladder. The total is split equally over k certificates
  // maturing every s months (terms s, 2s, ... ks). Rates are APYs, so $1 grows to (1 + APY)^(m/12)
  // after m months whatever the compounding.
  //   Standard: dividends = D x ((1 + a)^(T/12) - 1).
  //   Bump-up (one bump): start at a - cost; if rates rise by x points at month M < T, the rate
  //     is raised to a - cost + x for the rest of the term:
  //     value = D x (1 + a - cost)^(M/12) x (1 + a - cost + x)^((T - M)/12).
  //   Add-on: APY a' = a - cost, monthly growth q = (1 + a')^(1/12), deposits A at the end of
  //     months 1 .. T-1: value = D q^T + A (q^T - q) / (q - 1)   (q = 1: D + A (T - 1)).
  //     The standard comparison puts the same A each month in savings at the savings APY.
  // Verified (scratchpad cu5/tests/cul.test.js): $10,000 for 60 months at 4.05% APY = $2,195.80;
  // bump-up 60 months, 3.85% then 4.35% after 12 months = $10,000 x 1.0385 x 1.0435^4 - 10,000
  // = $2,313.35; add-on 12 months at 3.5% APY with $100/month = closed form and a month-by-month
  // loop agree; 0% everywhere returns only the money put in.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function pct(x) { return (x * 100).toFixed(2) + '%'; }

  function grow(D, apy, months) { return D * Math.pow(1 + apy, months / 12); }
  function annuity(A, apy, months) {
    // End-of-month deposits A in months 1 .. months-1, value at month `months`.
    if (months < 2 || A === 0) return 0;
    var q = Math.pow(1 + apy, 1 / 12);
    return Math.abs(q - 1) < 1e-12 ? A * (months - 1) : A * (Math.pow(q, months) - q) / (q - 1);
  }

  function rung(type, D, a, T, o) {
    var std = grow(D, a, T) - D, row = { term: T, deposit: D, added: 0, std: std, apyText: pct(a) };
    if (type === 'bump') {
      var start = Math.max(0, a - o.bumpCost);
      if (o.riseMonth < T && o.rise > 0) {
        var raised = start + o.rise;
        row.value = grow(D, start, o.riseMonth) * Math.pow(1 + raised, (T - o.riseMonth) / 12);
        row.apyText = pct(start) + ' → ' + pct(raised);
      } else {
        row.value = grow(D, start, T);
        row.apyText = pct(start);
      }
      row.stdValue = D + std;
    } else if (type === 'addon') {
      var addApy = Math.max(0, a - o.addCost);
      row.added = T > 1 ? o.add * (T - 1) : 0;
      row.value = grow(D, addApy, T) + annuity(o.add, addApy, T);
      row.apyText = pct(addApy);
      row.std = std + annuity(o.add, o.savings, T) - row.added;
      row.stdValue = D + std + annuity(o.add, o.savings, T);
    } else {
      row.value = D + std;
      row.stdValue = row.value;
    }
    row.dividends = row.value - D - row.added;
    return row;
  }

  function clear() {
    ['culDiv', 'culStd', 'culDiff', 'culAvg', 'culEach', 'culEvery', 'culPaid'].forEach(function (id) { set(id, '–'); });
    set('culDiffNote', '');
    document.getElementById('culTable').innerHTML = '';
  }

  function update() {
    var total = num('culTotal'), k = parseInt(document.getElementById('culRungs').value, 10),
        s = parseInt(document.getElementById('culSpacing').value, 10), type = document.getElementById('culType').value,
        o = { bumpCost: num('culBumpCost') / 100, rise: num('culRise') / 100, riseMonth: Math.round(num('culRiseMonth')),
              add: num('culAddMonthly'), addCost: num('culAddCost') / 100, savings: num('culSavings') / 100 };
    document.getElementById('culBumpWrap').hidden = type !== 'bump';
    document.getElementById('culAddWrap').hidden = type !== 'addon';
    set('culTypeHint', type === 'bump' ? 'Lets you raise the rate once during the term if the credit union\'s rate goes up.'
      : type === 'addon' ? 'Lets you keep adding money to the certificate after you open it.' : 'A fixed rate and a single opening deposit.');
    var apys = [];
    for (var i = 1; i <= 5; i++) {
      document.getElementById('culRow' + i).hidden = i > k;
      set('culApyLabel' + i, (i * s) + '-month certificate APY');
      apys.push(num('culApy' + i) / 100);
    }
    var used = apys.slice(0, k);
    var bad = isNaN(total) || total < 0 || total > 1e10 || isNaN(k) || isNaN(s) || used.some(function (a) { return isNaN(a) || a < 0 || a > 0.2; });
    if (type === 'bump') bad = bad || isNaN(o.bumpCost) || o.bumpCost < 0 || o.bumpCost > 0.1 || isNaN(o.rise) || o.rise < 0 || o.rise > 0.2 ||
                              isNaN(o.riseMonth) || o.riseMonth < 1 || o.riseMonth > 60;
    if (type === 'addon') bad = bad || isNaN(o.add) || o.add < 0 || o.add > 1e8 || isNaN(o.addCost) || o.addCost < 0 || o.addCost > 0.1 ||
                               isNaN(o.savings) || o.savings < 0 || o.savings > 0.2;
    var error = document.getElementById('culError');
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter a total of $0 or more, APYs from 0 to 20%, rate adjustments from 0 to 10 points (rise up to 20), a month from 1 to 60 and add-ons of $0 or more.';
      clear();
      return;
    }
    var D = total / k, rows = [], div = 0, std = 0, paid = 0, added = 0;
    for (var j = 0; j < k; j++) {
      var row = rung(type, D, used[j], (j + 1) * s, o);
      rows.push(row);
      div += row.dividends; std += row.std; paid += row.value; added += row.added;
    }
    var avg = used.reduce(function (x, y) { return x + y; }, 0) / k;
    set('culDiv', money.format(div));
    set('culStdLabel', type === 'addon' ? 'Standard ladder + savings' : 'With standard certificates');
    set('culStd', money.format(std));
    var diff = div - std;
    set('culDiff', (diff < 0 ? '−' : '+') + money.format(Math.abs(diff)));
    set('culDiffNote', type === 'standard' ? 'Pick bump-up or add-on to compare.'
      : diff >= 0 ? 'The ' + (type === 'bump' ? 'bump-up' : 'add-on') + ' feature comes out ahead.' : 'Standard certificates come out ahead with these assumptions.');
    set('culAvg', pct(avg));
    set('culEach', money.format(D));
    set('culEvery', 'Every ' + s + ' months, last at month ' + (k * s));
    set('culPaid', money.format(paid) + (added > 0 ? ' (incl. ' + money.format(added) + ' added)' : ''));
    document.getElementById('culTable').innerHTML = rows.map(function (r) {
      return '<tr><td>' + r.term + '</td><td>' + money.format(r.deposit) + '</td><td>' + r.apyText + '</td><td>' + money.format(r.added) +
             '</td><td>' + money.format(r.dividends) + '</td><td>' + money.format(r.std) + '</td><td>' + money.format(r.value) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('culForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
